CREATE TABLE IF NOT EXISTS tb_ai_provider_usage_call (
    ai_provider_usage_call_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    call_id CHAR(36) NOT NULL,
    operation_id CHAR(36) NOT NULL,
    attempt_no SMALLINT UNSIGNED NOT NULL,
    feature_key VARCHAR(32) NOT NULL,
    stage_key VARCHAR(64) NOT NULL,
    request_mode VARCHAR(16) NOT NULL,
    provider VARCHAR(32) NOT NULL,
    requested_model VARCHAR(128) NOT NULL,
    resolved_model VARCHAR(128) NULL,
    provider_request_id VARCHAR(128) NULL,
    attempt_status VARCHAR(32) NOT NULL,
    http_status SMALLINT UNSIGNED NULL,
    error_code VARCHAR(64) NULL,
    input_tokens BIGINT UNSIGNED NULL,
    cached_input_tokens BIGINT UNSIGNED NULL,
    output_tokens BIGINT UNSIGNED NULL,
    reasoning_tokens BIGINT UNSIGNED NULL,
    total_tokens BIGINT UNSIGNED NULL,
    cost_usd DECIMAL(18, 9) NULL,
    cost_source VARCHAR(24) NOT NULL,
    pricing_version VARCHAR(64) NULL,
    latency_ms INT UNSIGNED NOT NULL,
    product_id BIGINT UNSIGNED NULL,
    episode_id BIGINT UNSIGNED NULL,
    session_id VARCHAR(64) NULL,
    batch_run_id VARCHAR(64) NULL,
    scope_key VARCHAR(128) NULL,
    attempt_started_at DATETIME(6) NOT NULL,
    record_hash CHAR(64) NOT NULL,
    created_date DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (ai_provider_usage_call_id),
    UNIQUE KEY uq_ai_provider_usage_call_id (call_id),
    UNIQUE KEY uq_ai_provider_usage_operation_attempt (operation_id, attempt_no),
    KEY ix_ai_provider_usage_started (attempt_started_at),
    KEY ix_ai_provider_usage_feature_stage_started (feature_key, stage_key, attempt_started_at),
    KEY ix_ai_provider_usage_batch_started (batch_run_id, attempt_started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
